def print_board(board):
    '''Funktion zum Drucken des Tic-Tac-Toe-Spielfelds'''
    for i in range(3):
        for j in range(3):
            print(board[i][j], end = " | ")
        print()

def check_win(board):
    '''Funktion zum Überprüfen, ob das Spiel mit einem Sieg beendet wurde'''
    # Überprüfen der Reihen
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] and board[i][0] != " ":
